# ============================================================
# ПУБЛИКАЦИЯ В КАНАЛ
# ============================================================

def publish_listing(
    data
):

    text = build_listing(
        data
    )

    photos = data[
        "photos"
    ]

    # Канал не указан
    if not CHANNEL_USERNAME:

        return {

            "ok":
                False,

            "description":
                "CHANNEL_USERNAME is empty"
        }

    # Публикация с фотографиями
    if photos:

        return send_album(

            CHANNEL_USERNAME,

            photos,

            text
        )

    # Публикация без фотографий
    return api(

        "sendMessage",

        {

            "chat_id":
                CHANNEL_USERNAME,

            "text":
                text,

            "parse_mode":
                "HTML"
        }
    )


def remove_moderation_requests_for_user(
    chat_id
):

    for request_id, item in list(
        moderation_requests.items()
    ):

        if item.get(
            "user_chat_id"
        ) == chat_id:

            moderation_requests.pop(
                request_id,
                None
            )


def edit_moderation_message(
    chat_id,
    message_id,
    text,
    keyboard=None
):

    if not chat_id or not message_id:
        return

    data = {
        "chat_id": chat_id,
        "message_id": message_id,
        "text": text,
        "parse_mode": "HTML"
    }

    if keyboard:
        data["reply_markup"] = {
            "inline_keyboard": keyboard
        }

    api(
        "editMessageText",
        data
    )


def submit_for_moderation(
    chat_id
):

    global next_moderation_id

    if chat_id not in states:
        return

    if not ADMIN_CHAT_ID:

        send(

            chat_id,

            "<b>⚠️ Модератор пока не настроен.</b>\n\n"

            "В Render → Environment добавьте "
            "переменную <code>ADMIN_CHAT_ID</code>."
        )

        return

    if states[chat_id]["step"] == "moderation":

        send(

            chat_id,

            "⏳ <b>Объявление уже отправлено "
            "на проверку.</b>\n\n"

            "Дождитесь решения администратора."
        )

        return

    data = states[
        chat_id
    ]["data"]

    # Нужен для связи объявления с пользователем в Supabase.
    data["_telegram_id"] = chat_id

    request_id = next_moderation_id

    next_moderation_id += 1

    moderation_requests[
        request_id
    ] = {

        "user_chat_id":
            chat_id,

        "message_chat_id":
            None,

        "message_id":
            None
    }

    states[
        chat_id
    ]["step"] = "moderation"

    text = build_listing(
        data
    )

    photos = data[
        "photos"
    ]

    admin_header = (

        "<b>🛡 НОВОЕ ОБЪЯВЛЕНИЕ "
        "НА МОДЕРАЦИЮ</b>\n\n"

        f"👤 ID автора: <code>{chat_id}</code>\n"

        f"🔢 Заявка: <code>#{request_id}</code>\n\n"
    )

    # Если есть фотографии — отправляем их администратору
    # компактным альбомом.
    if photos:

        result = send_album(

            ADMIN_CHAT_ID,

            photos,

            text
        )

        if not result.get(
            "ok"
        ):

            moderation_requests.pop(
                request_id,
                None
            )

            states[
                chat_id
            ]["step"] = "preview"

            send(

                chat_id,

                "<b>⚠️ Не удалось отправить "
                "объявление администратору.</b>\n\n"

                "Попробуйте ещё раз."
            )

            return

        control = send(

            ADMIN_CHAT_ID,

            admin_header +

            f"📷 Фотографий: "
            f"<b>{len(photos)}</b>\n\n"

            "Выберите действие:",

            moderation_keyboard(
                request_id
            )
        )

    # Без фотографий — всё объявление сразу
    # отправляем администратору вместе с кнопками.
    else:

        control = send(

            ADMIN_CHAT_ID,

            admin_header +

            text +

            "\n\n"
            "Выберите действие:",

            moderation_keyboard(
                request_id
            )
        )

    if not control.get(
        "ok"
    ):

        moderation_requests.pop(
            request_id,
            None
        )

        states[
            chat_id
        ]["step"] = "preview"

        send(

            chat_id,

            "<b>⚠️ Не удалось отправить "
            "объявление на модерацию.</b>\n\n"

            "Попробуйте ещё раз."
        )

        return

    result_data = control.get(
        "result",
        {}
    )

    moderation_requests[
        request_id
    ]["message_chat_id"] = (
        result_data
        .get("chat", {})
        .get("id")
    )

    moderation_requests[
        request_id
    ]["message_id"] = (
        result_data
        .get("message_id")
    )

    send(

        chat_id,

        "<b>📨 Объявление отправлено "
        "на проверку.</b>\n\n"

        "После решения администратора "
        "вы получите уведомление.",

        main_menu()
    )



def moderator_is_allowed(admin_user_id):
    try:
        return bool(ADMIN_CHAT_ID) and int(admin_user_id) == int(ADMIN_CHAT_ID)
    except Exception:
        return False


def moderation_control_text(request_id):
    item = moderation_requests.get(request_id)
    if not item:
        return None
    user_chat_id = item["user_chat_id"]
    if user_chat_id not in states:
        return None
    data = states[user_chat_id]["data"]
    return (
        "<b>🛡 ОБЪЯВЛЕНИЕ НА МОДЕРАЦИИ</b>\n\n"
        f"👤 ID автора: <code>{user_chat_id}</code>\n"
        f"🔢 Заявка: <code>#{request_id}</code>\n\n"
        f"{build_listing(data)}\n\n"
        "Выберите действие:"
    )


def show_moderation_editor(admin_chat_id, request_id):
    if not moderator_is_allowed(admin_chat_id):
        return
    item = moderation_requests.get(request_id)
    if not item or item["user_chat_id"] not in states:
        send(admin_chat_id, "⚠️ Заявка уже обработана или недоступна.")
        return
    moderator_sessions[admin_chat_id] = {"request_id": request_id, "step": "menu"}
    send(
        admin_chat_id,
        "<b>✏️ РЕДАКТИРОВАНИЕ ОБЪЯВЛЕНИЯ</b>\n\nВыберите, что нужно исправить:",
        moderation_edit_menu(request_id)
    )


def show_updated_moderation(admin_chat_id, request_id):
    text = moderation_control_text(request_id)
    item = moderation_requests.get(request_id)
    if not text or not item:
        return
    edit_moderation_message(
        item.get("message_chat_id"),
        item.get("message_id"),
        text,
        moderation_keyboard(request_id)
    )


def process_moderator_text(admin_chat_id, text):
    session = moderator_sessions.get(admin_chat_id)
    if not session:
        return False
    request_id = session.get("request_id")
    item = moderation_requests.get(request_id)
    if not item or item["user_chat_id"] not in states:
        moderator_sessions.pop(admin_chat_id, None)
        send(admin_chat_id, "⚠️ Заявка уже обработана или недоступна.")
        return True

    data = states[item["user_chat_id"]]["data"]
    step = session.get("step")
    text = text.strip()

    if not text:
        send(admin_chat_id, "Введите новое значение.")
        return True

    if step == "price":
        data["price"] = text.replace(" ", "").replace(",", ".")
    elif step == "district":
        data["district"] = text
    elif step == "description":
        data["description"] = "" if text.lower() in {"ничего", "нет", "нечего", "без описания", "пропустить", "-"} else text
    elif step == "contact":
        data["contact"] = text
    elif step.startswith("detail_"):
        try:
            index = int(step.split("_", 1)[1])
        except ValueError:
            moderator_sessions.pop(admin_chat_id, None)
            return True
        fields = CATEGORIES[data["category_key"]]["fields"]
        if index < len(fields):
            data["details"][fields[index][0]] = text
    else:
        return False

    moderator_sessions.pop(admin_chat_id, None)
    send(admin_chat_id, "✅ <b>Изменение сохранено.</b>\n\nПроверьте объявление ещё раз.")
    show_updated_moderation(admin_chat_id, request_id)
    return True

def moderate_publish(
    request_id,
    admin_user_id,
    callback_id
):

    # Проверяем, что кнопку нажал именно
    # назначенный администратор.
    try:

        if int(
            admin_user_id
        ) != int(
            ADMIN_CHAT_ID
        ):

            answer(

                callback_id,

                "⛔ У вас нет прав администратора.",

                True
            )

            return

    except Exception:

        answer(

            callback_id,

            "⚠️ ADMIN_CHAT_ID настроен неправильно.",

            True
        )

        return

    item = moderation_requests.get(
        request_id
    )

    if not item:

        answer(

            callback_id,

            "Заявка уже обработана.",

            True
        )

        return

    user_chat_id = item[
        "user_chat_id"
    ]

    if user_chat_id not in states:

        moderation_requests.pop(
            request_id,
            None
        )

        answer(

            callback_id,

            "Объявление больше недоступно.",

            True
        )

        return

    data = states[
        user_chat_id
    ]["data"]

    result = publish_listing(
        data
    )

    if not result.get(
        "ok"
    ):

        answer(

            callback_id,

            "⚠️ Не удалось опубликовать.",

            True
        )

        send(

            admin_user_id,

            "<b>⚠️ Не удалось опубликовать "
            "объявление.</b>\n\n"

            "Проверьте:\n"
            "• бот является администратором канала;\n"
            "• у бота есть право публиковать сообщения;\n"
            "• CHANNEL_USERNAME указан правильно."
        )

        return

    # Сохраняем объявление в каталоге ДО очистки states.
    register_published_listing(
        data,
        result,
        user_chat_id=user_chat_id
    )

    moderation_requests.pop(
        request_id,
        None
    )

    moderator_sessions.pop(
        int(admin_user_id),
        None
    )

    states.pop(
        user_chat_id,
        None
    )

    answer(

        callback_id,

        "🟢 Опубликовано!"
    )

    edit_moderation_message(

        item.get(
            "message_chat_id"
        ),

        item.get(
            "message_id"
        ),

        "<b>🟢 ОПУБЛИКОВАНО</b>\n\n"

        f"Заявка: <code>#{request_id}</code>\n"

        f"Автор ID: <code>{user_chat_id}</code>"
    )

    send(

        user_chat_id,

        "<b>🎉 Объявление опубликовано!</b>\n\n"

        "Оно прошло модерацию и добавлено "
        "в <b>MADLOBA MARKET | БАТУМИ</b>.",

        main_menu()
    )


def moderate_reject(
    request_id,
    admin_user_id,
    callback_id
):

    try:

        if int(
            admin_user_id
        ) != int(
            ADMIN_CHAT_ID
        ):

            answer(

                callback_id,

                "⛔ У вас нет прав администратора.",

                True
            )

            return

    except Exception:

        answer(

            callback_id,

            "⚠️ ADMIN_CHAT_ID настроен неправильно.",

            True
        )

        return

    item = moderation_requests.get(
        request_id
    )

    if not item:

        answer(

            callback_id,

            "Заявка уже обработана.",

            True
        )

        return

    user_chat_id = item[
        "user_chat_id"
    ]

    # Удаляем заявку из очереди.
    # Само объявление сохраняем, чтобы автор
    # мог его исправить и отправить повторно.
    moderation_requests.pop(
        request_id,
        None
    )

    moderator_sessions.pop(
        int(admin_user_id),
        None
    )

    if user_chat_id in states:

        states[
            user_chat_id
        ]["step"] = "preview"

        send(

            user_chat_id,

            "<b>❌ Объявление не прошло "
            "модерацию.</b>\n\n"

            "Администратор отклонил объявление.\n\n"

            "Вы можете изменить данные "
            "и отправить его на проверку повторно.",

            [

                [

                    {

                        "text":
                            "✏️ Изменить объявление",

                        "callback_data":
                            "edit_menu"
                    }
                ],

                [

                    {

                        "text":
                            "🔄 Начать заново",

                        "callback_data":
                            "restart_post"
                    }
                ],

                [

                    {

                        "text":
                            "❌ Удалить",

                        "callback_data":
                            "cancel_post"
                    }
                ]
            ]
        )

    answer(

        callback_id,

        "🔴 Объявление отклонено."
    )

    edit_moderation_message(

        item.get(
            "message_chat_id"
        ),

        item.get(
            "message_id"
        ),

        "<b>🔴 ОТКЛОНЕНО</b>\n\n"

        f"Заявка: <code>#{request_id}</code>\n"

        f"Автор ID: <code>{user_chat_id}</code>"
    )


# ============================================================
# ОБРАБОТКА ТЕКСТА
# ============================================================

def process_text(
    chat_id,
    text
):

    if chat_id not in states:

        return False


    state = states[
        chat_id
    ]

    data = state[
        "data"
    ]

    step = state[
        "step"
    ]


    text = text.strip()


    # ========================================================
    # ОЖИДАНИЕ МОДЕРАЦИИ
    # ========================================================

    if step == "moderation":

        send(

            chat_id,

            "⏳ <b>Объявление находится "
            "на модерации.</b>\n\n"

            "Дождитесь решения администратора."
        )

        return True


    # Отмена
    if text.lower() in (
        "отмена",
        "cancel"
    ):

        states.pop(
            chat_id,
            None
        )

        send(

            chat_id,

            "❌ Объявление отменено.",

            main_menu()
        )

        return True


    # ========================================================
    # ХАРАКТЕРИСТИКИ
    # ========================================================

    if step.startswith(
        "detail_"
    ):

        index = int(

            step.split(
                "_"
            )[1]
        )


        fields = CATEGORIES[
            data[
                "category_key"
            ]
        ]["fields"]


        if index < len(
            fields
        ):

            data[
                "details"
            ][
                fields[index][0]
            ] = text


        ask_detail(

            chat_id,

            index + 1
        )


        return True


    # ========================================================
    # РЕДАКТИРОВАНИЕ ХАРАКТЕРИСТИК
    # ========================================================

    if step.startswith(
        "edit_detail_"
    ):

        index = int(

            step.rsplit(
                "_",
                1
            )[1]
        )


        fields = CATEGORIES[
            data[
                "category_key"
            ]
        ]["fields"]


        if index < len(
            fields
        ):

            data[
                "details"
            ][
                fields[index][0]
            ] = text


        preview(
            chat_id
        )


        return True


    # ========================================================
    # СУММА
    # ========================================================

    if step in (
        "amount",
        "edit_amount"
    ):

        # Оставляем только нормальную цену.
        cleaned = text.replace(
            " ",
            ""
        ).replace(
            ",",
            "."
        )

        data[
            "price"
        ] = cleaned


        if step == "amount":

            ask_district(
                chat_id
            )

        else:

            preview(
                chat_id
            )


        return True


    # ========================================================
    # ЛОКАЦИЯ
    # ========================================================

    if step in (
        "district",
        "edit_district"
    ):

        data[
            "district"
        ] = text


        if step == "district":

            ask_description(
                chat_id
            )

        else:

            preview(
                chat_id
            )


        return True


    # ========================================================
    # ОПИСАНИЕ
    # ========================================================

    if step in (
        "description",
        "edit_description"
    ):

        # Пустые/служебные ответы не публикуем.
        if text.lower() in {

            "ничего",
            "нет",
            "нечего",
            "без описания",
            "пропустить",
            "-"

        }:

            data[
                "description"
            ] = ""

        else:

            data[
                "description"
            ] = text


        if step == "description":

            ask_photos(
                chat_id
            )

        else:

            preview(
                chat_id
            )


        return True


    # ========================================================
    # ФОТО
    # ========================================================

    if step == "photos":

        send(

            chat_id,

            "📷 Отправьте фотографию "
            "или нажмите <b>✅ Готово</b>."
        )

        return True


    # ========================================================
    # КОНТАКТ
    # ========================================================

    if step in (
        "contact",
        "edit_contact"
    ):

        data[
            "contact"
        ] = text


        preview(
            chat_id
        )


        return True


    return False


# ============================================================
# ОБРАБОТКА UPDATE
# ============================================================

def handle(
    update
):

    # ========================================================
    # MESSAGE
    # ========================================================

    if "message" in update:

        message = update[
            "message"
        ]

        chat_id = message[
            "chat"
        ]["id"]


        # ====================================================
        # ФОТО
        # ====================================================

        if "photo" in message:

            if (

                chat_id in states

                and

                states[
                    chat_id
                ]["step"] == "photos"

            ):

                photos = states[
                    chat_id
                ]["data"][
                    "photos"
                ]


                if len(
                    photos
                ) < MAX_PHOTOS:

                    photos.append(

                        message[
                            "photo"
                        ][-1][
                            "file_id"
                        ]
                    )


                send(

                    chat_id,

                    f"📷 Фото добавлено: "
                    f"<b>{len(photos)}/{MAX_PHOTOS}</b>",

                    [

                        [

                            {

                                "text":
                                    "✅ Готово",

                                "callback_data":
                                    "photos_done"
                            }
                        ]
                    ]
                )


            return


        text = message.get(
            "text",
            ""
        )


        # ====================================================
        # РЕДАКТИРОВАНИЕ ОБЪЯВЛЕНИЯ МОДЕРАТОРОМ
        # ====================================================

        if (
            ADMIN_CHAT_ID
            and str(chat_id) == str(ADMIN_CHAT_ID)
            and chat_id in moderator_sessions
            and process_moderator_text(chat_id, text)
        ):
            return


        # ====================================================
        # TELEGRAM DEEP LINKS
        # ====================================================

        if text.startswith("/start") and len(text.split(" ", 1)) > 1:

            start_param = text.split(" ", 1)[1].strip()

            if start_param == "post":
                start_post(chat_id)
                return

            if start_param.startswith("cat_"):
                key = start_param[4:]
                if key in CATEGORIES:
                    send(
                        chat_id,
                        f"<b>{esc(CATEGORIES[key]['name'])}</b>\n\n"
                        "Выберите раздел:",
                        category_menu(key)
                    )
                return

        # ====================================================
        # START
        # ====================================================

        if (

            text.startswith(
                "/start"
            )

            or

            text.strip()
            ==
            "🏠 Главное меню"

        ):

            remove_moderation_requests_for_user(
                chat_id
            )

            states.pop(
                chat_id,
                None
            )


            send(

                chat_id,

                "<b>"
                "🛒 MADLOBA MARKET | БАТУМИ"
                "</b>\n\n"

                "Главная доска объявлений Батуми.\n\n"

                "Купи · Продай · Сдай · Найди\n\n"

                "<b>"
                "Выберите категорию:"
                "</b>",

                main_menu()
            )


            return


        # ====================================================
        # ПУБЛИКАЦИЯ ГЛАВНОГО МЕНЮ В КАНАЛ
        # ====================================================

        if text.strip() == "/channel_menu":

            if not ADMIN_CHAT_ID or str(chat_id) != str(ADMIN_CHAT_ID):

                send(
                    chat_id,
                    "⛔ Эта команда доступна только администратору."
                )
                return

            if not CHANNEL_USERNAME:

                send(
                    chat_id,
                    "❌ Не указан CHANNEL_USERNAME в Render."
                )
                return

            result = send(
                CHANNEL_USERNAME,
                CHANNEL_MENU_TEXT,
                channel_main_menu()
            )

            if result.get("ok") and result.get("result", {}).get("message_id"):

                message_id = result["result"]["message_id"]

                pin_result = api(
                    "pinChatMessage",
                    {
                        "chat_id": CHANNEL_USERNAME,
                        "message_id": message_id,
                        "disable_notification": True
                    }
                )

                if pin_result.get("ok"):
                    send(
                        chat_id,
                        "✅ Главное меню опубликовано и закреплено в канале."
                    )
                else:
                    send(
                        chat_id,
                        "✅ Главное меню опубликовано в канале.\n\n"
                        "⚠️ Автоматически закрепить его не удалось. "
                        "Проверь права бота на управление публикациями."
                    )
            else:
                send(
                    chat_id,
                    "❌ Не удалось опубликовать главное меню.\n\n"
                    f"<code>{esc(str(result))}</code>"
                )

            return


        # ====================================================
        # TELEGRAM ID
        # ====================================================

        if text.strip() == "/id":

            send(

                chat_id,

                "🆔 Ваш Telegram ID:\n\n"
                f"<code>{chat_id}</code>\n\n"
                "Этот номер нужно указать в Render "
                "как <code>ADMIN_CHAT_ID</code>."
            )

            return


        # ====================================================
        # АКТИВНАЯ ФОРМА
        # ====================================================

        if (

            chat_id in states

            and

            process_text(
                chat_id,
                text
            )

        ):

            return


        # ====================================================
        # КОМАНДЫ
        # ====================================================

        if text.startswith(
            "/categories"
        ):

            send(

                chat_id,

                "📂 <b>Выберите категорию:</b>",

                main_menu()
            )


        elif text.startswith(
            "/post"
        ):

            start_post(
                chat_id
            )


        elif text.startswith(
            "/rules"
        ):

            send(

                chat_id,

                "<b>📋 Правила MADLOBA MARKET</b>\n\n"

                "• Только реальные объявления.\n"
                "• Запрещены мошенничество "
                "и незаконные товары.\n"
                "• Не публикуйте чужие "
                "персональные данные.\n"
                "• Не размещайте спам."
            )


        elif text.startswith(
            "/help"
        ):

            send(

                chat_id,

                "<b>ℹ️ MADLOBA MARKET</b>\n\n"

                "/start — главное меню\n"
                "/categories — категории\n"
                "/post — разместить объявление\n"
                "/rules — правила\n"
                "/help — помощь"
            )


        return


    # ========================================================
    # CALLBACK QUERY
    # ========================================================

    if "callback_query" not in update:

        return


    callback = update[
        "callback_query"
    ]


    chat_id = callback[
        "message"
    ]["chat"]["id"]


    data = callback.get(
        "data",
        ""
    )

    callback_from_id = callback[
        "from"
    ]["id"]


    # ========================================================
    # МОДЕРАЦИЯ
    # ========================================================

    if data.startswith("mod_edit_"):
        try:
            request_id = int(data[len("mod_edit_"):])
        except ValueError:
            answer(callback["id"], "Некорректный номер заявки.", True)
            return
        if not moderator_is_allowed(callback_from_id):
            answer(callback["id"], "⛔ У вас нет прав администратора.", True)
            return
        answer(callback["id"])
        show_moderation_editor(callback_from_id, request_id)
        return


    if data.startswith("mod_back_"):
        try:
            request_id = int(data[len("mod_back_"):])
        except ValueError:
            answer(callback["id"], "Некорректный номер заявки.", True)
            return
        if not moderator_is_allowed(callback_from_id):
            answer(callback["id"], "⛔ У вас нет прав администратора.", True)
            return
        moderator_sessions.pop(callback_from_id, None)
        answer(callback["id"])
        text = moderation_control_text(request_id)
        if text:
            send(callback_from_id, text, moderation_keyboard(request_id))
        return


    if data.startswith("mod_field_"):
        parts = data.split("_")
        if len(parts) != 4:
            answer(callback["id"], "Некорректная команда.", True)
            return
        field = parts[2]
        try:
            request_id = int(parts[3])
        except ValueError:
            answer(callback["id"], "Некорректный номер заявки.", True)
            return
        if not moderator_is_allowed(callback_from_id):
            answer(callback["id"], "⛔ У вас нет прав администратора.", True)
            return
        if request_id not in moderation_requests:
            answer(callback["id"], "Заявка уже обработана.", True)
            return
        prompts = {
            "price": "💰 <b>Новая цена</b>\n\nВведите только сумму. Например: <b>750</b>",
            "district": "📍 <b>Новая локация</b>\n\nВведите район или адрес.",
            "description": "📝 <b>Новое описание</b>\n\nВведите новый текст. Чтобы убрать описание — напишите <b>Пропустить</b>.",
            "contact": "📞 <b>Новый контакт</b>\n\nВведите телефон, Telegram или WhatsApp."
        }
        if field not in prompts:
            answer(callback["id"], "Неизвестное поле.", True)
            return
        moderator_sessions[callback_from_id] = {"request_id": request_id, "step": field}
        answer(callback["id"])
        send(callback_from_id, prompts[field])
        return


    if data.startswith("mod_details_"):
        try:
            request_id = int(data[len("mod_details_"):])
        except ValueError:
            answer(callback["id"], "Некорректный номер заявки.", True)
            return
        if not moderator_is_allowed(callback_from_id):
            answer(callback["id"], "⛔ У вас нет прав администратора.", True)
            return
        item = moderation_requests.get(request_id)
        if not item or item["user_chat_id"] not in states:
            answer(callback["id"], "Заявка уже обработана.", True)
            return
        moderator_sessions[callback_from_id] = {"request_id": request_id, "step": "details_menu"}
        answer(callback["id"])
        send(
            callback_from_id,
            "<b>📋 Характеристики</b>\n\nЧто изменить?",
            moderation_detail_menu(request_id, states[item["user_chat_id"]]["data"])
        )
        return


    if data.startswith("mod_detail_"):
        parts = data.split("_")
        if len(parts) != 4:
            answer(callback["id"], "Некорректная команда.", True)
            return
        try:
            request_id = int(parts[2])
            index = int(parts[3])
        except ValueError:
            answer(callback["id"], "Некорректная заявка.", True)
            return
        if not moderator_is_allowed(callback_from_id):
            answer(callback["id"], "⛔ У вас нет прав администратора.", True)
            return
        item = moderation_requests.get(request_id)
        if not item or item["user_chat_id"] not in states:
            answer(callback["id"], "Заявка уже обработана.", True)
            return
        data_listing = states[item["user_chat_id"]]["data"]
        fields = CATEGORIES[data_listing["category_key"]]["fields"]
        if index >= len(fields):
            answer(callback["id"], "Характеристика не найдена.", True)
            return
        moderator_sessions[callback_from_id] = {"request_id": request_id, "step": f"detail_{index}"}
        answer(callback["id"])
        send(callback_from_id, f"<b>{esc(fields[index][1])}</b>\n\nВведите новое значение.")
        return


    if data.startswith(
        "mod_publish_"
    ):

        try:

            request_id = int(
                data[
                    len("mod_publish_"):
                ]
            )

        except ValueError:

            answer(

                callback["id"],

                "Некорректный номер заявки.",

                True
            )

            return

        moderate_publish(

            request_id,

            callback_from_id,

            callback["id"]
        )

        return


    if data.startswith(
        "mod_reject_"
    ):

        try:

            request_id = int(
                data[
                    len("mod_reject_"):
                ]
            )

        except ValueError:

            answer(

                callback["id"],

                "Некорректный номер заявки.",

                True
            )

            return

        moderate_reject(

            request_id,

            callback_from_id,

            callback["id"]
        )

        return


    answer(
        callback["id"]
    )


    # ========================================================
    # ГЛАВНОЕ МЕНЮ
    # ========================================================

    if data == "back_main":

        send(

            chat_id,

            "<b>"
            "🛒 MADLOBA MARKET | БАТУМИ"
            "</b>\n\n"

            "Выберите категорию:",

            main_menu()
        )

        return


    # ========================================================
    # КАТЕГОРИЯ
    # ========================================================

    if data.startswith(
        "cat_"
    ):

        key = data[
            4:
        ]


        if key in CATEGORIES:

            send(

                chat_id,

                f"<b>"
                f"{esc(CATEGORIES[key]['name'])}"
                f"</b>\n\n"
                "Выберите раздел:",

                category_menu(
                    key
                )
            )


        return


    # ========================================================
    # ПРОСМОТР КАТЕГОРИИ
    # ========================================================

    if data.startswith(
        "browsepage_"
    ):

        parts = data.split(
            "_",
            3
        )

        if len(parts) != 4:
            return

        key = parts[1]
        sub = parts[2]

        try:
            page = int(parts[3])
        except ValueError:
            return

        if key not in CATEGORIES:
            return

        send_listing_catalog(
            chat_id,
            key,
            sub,
            page
        )

        return



    if data.startswith(
        "browse_"
    ):

        parts = data.split(
            "_",
            2
        )

        if len(parts) < 3:
            return

        key = parts[1]
        sub = parts[2]

        if key not in CATEGORIES:
            return

        send_listing_catalog(
            chat_id,
            key,
            sub,
            0
        )

        return


    # ========================================================
    # СОЗДАНИЕ ОБЪЯВЛЕНИЯ
    # ========================================================

    if data == "post":

        start_post(
            chat_id
        )

        return


    # ========================================================
    # ВЫБОР КАТЕГОРИИ
    # ========================================================

    if data.startswith(
        "postcat_"
    ):

        key = data[
            8:
        ]


        if key not in CATEGORIES:

            return


        states[
            chat_id
        ] = {

            "step":
                "subcategory",

            "data":
                blank_listing()
        }


        states[
            chat_id
        ]["data"][
            "category_key"
        ] = key


        states[
            chat_id
        ]["data"][
            "category"
        ] = CATEGORIES[
            key
        ]["name"]


        send(

            chat_id,

            "<b>"
            "1 · Категория"
            "</b>\n\n"

            "Выберите раздел:",

            post_sub_menu(
                key
            )
        )


        return


    # ========================================================
    # ПОДКАТЕГОРИЯ
    # ========================================================

    if data.startswith(
        "postsub_"
    ):

        parts = data.split(
            "_",
            2
        )


        if len(parts) < 3:

            return


        key = parts[
            1
        ]

        sub = parts[
            2
        ]


        if (

            chat_id not in states

            or

            key not in CATEGORIES

            or

            sub not in CATEGORIES[
                key
            ]["subs"]

        ):

            return


        listing = states[
            chat_id
        ]["data"]


        listing[
            "subcategory_key"
        ] = sub


        listing[
            "subcategory"
        ] = CATEGORIES[
            key
        ]["subs"][
            sub
        ]


        states[
            chat_id
        ]["step"] = "type"


        send(

            chat_id,

            "<b>"
            "2 · Тип объявления"
            "</b>\n\n"

            "Выберите действие:",

            post_type_menu(
                key
            )
        )


        return


    # ========================================================
    # ТИП ОБЪЯВЛЕНИЯ
    # ========================================================

    if data.startswith(
        "posttype_"
    ):

        if chat_id not in states:

            return


        type_key = data[
            9:
        ]


        listing = states[
            chat_id
        ]["data"]


        listing[
            "type_key"
        ] = type_key


        # Для недвижимости seek = Сниму.
        if (

            listing[
                "category_key"
            ]

            ==

            "realestate"

            and

            type_key
            ==
            "seek"

        ):

            listing[
                "type"
            ] = "🔎 Сниму"

        else:

            listing[
                "type"
            ] = TYPE_NAMES.get(

                type_key,

                type_key
            )


        ask_detail(
            chat_id,
            0
        )


        return


    # ========================================================
    # ВАЛЮТА
    # ========================================================

    if data.startswith(
        "currency_"
    ):

        if chat_id not in states:

            return


        currency = data[
            9:
        ]


        listing = states[
            chat_id
        ]["data"]


        editing = (

            states[
                chat_id
            ]["step"]

            ==

            "edit_currency"
        )


        listing[
            "currency"
        ] = currency


        # Договорная
        if currency == "negotiable":

            listing[
                "price"
            ] = "Договорная"


            if editing:

                preview(
                    chat_id
                )

            else:

                ask_district(
                    chat_id
                )


            return


        # Бесплатно
        if currency == "free":

            listing[
                "price"
            ] = "Бесплатно"


            if editing:

                preview(
                    chat_id
                )

            else:

                ask_district(
                    chat_id
                )


            return


        # Обычная цена
        ask_amount(

            chat_id,

            editing
        )


        return


    # ========================================================
    # ФОТО ГОТОВЫ
    # ========================================================

    if data == "photos_done":

        if (

            chat_id in states

            and

            states[
                chat_id
            ]["step"] == "photos"

        ):

            ask_contact(
                chat_id
            )


        return


    # ========================================================
    # ФОТО ПРОПУСТИТЬ
    # ========================================================

    if data == "photos_skip":

        if chat_id in states:

            states[
                chat_id
            ]["data"][
                "photos"
            ] = []


            ask_contact(
                chat_id
            )


        return


    # ========================================================
    # МЕНЮ РЕДАКТИРОВАНИЯ
    # ========================================================

    if data == "edit_menu":

        if chat_id in states:

            send(

                chat_id,

                "<b>"
                "✏️ Что хотите изменить?"
                "</b>",

                edit_menu()
            )


        return


    # ========================================================
    # ХАРАКТЕРИСТИКИ
    # ========================================================

    if data == "edit_details":

        if chat_id in states:

            edit_details_menu(
                chat_id
            )


        return


    # ========================================================
    # ЦЕНА
    # ========================================================

    if data == "edit_price":

        if chat_id in states:

            states[
                chat_id
            ]["step"] = (
                "edit_currency"
            )


            send(

                chat_id,

                "<b>"
                "💰 Цена"
                "</b>\n\n"

                "Выберите валюту или вариант:",

                currency_menu()
            )


        return


    # ========================================================
    # ЛОКАЦИЯ / ОПИСАНИЕ / КОНТАКТ
    # ========================================================

    if data in (

        "edit_district",

        "edit_description",

        "edit_contact"

    ):

        if chat_id not in states:

            return


        prompts = {

            "edit_district":

                "<b>"
                "📍 Локация"
                "</b>\n\n"

                "Введите новую локацию.",


            "edit_description":

                "<b>"
                "📝 Описание"
                "</b>\n\n"

                "Введите новое описание.",


            "edit_contact":

                "<b>"
                "📞 Контакт"
                "</b>\n\n"

                "Введите новый контакт."
        }


        states[
            chat_id
        ]["step"] = data


        send(

            chat_id,

            prompts[data]
        )


        return


    # ========================================================
    # ФОТО
    # ========================================================

    if data == "edit_photos":

        if chat_id in states:

            states[
                chat_id
            ]["data"][
                "photos"
            ] = []


            ask_photos(
                chat_id
            )


        return


    # ========================================================
    # ОТДЕЛЬНАЯ ХАРАКТЕРИСТИКА
    # ========================================================

    if data.startswith(
        "edit_detail_"
    ):

        if chat_id not in states:

            return


        index = int(

            data.rsplit(
                "_",
                1
            )[1]
        )


        fields = CATEGORIES[

            states[
                chat_id
            ]["data"][
                "category_key"
            ]

        ]["fields"]


        if index < len(
            fields
        ):

            states[
                chat_id
            ]["step"] = (

                f"edit_detail_{index}"
            )


            send(

                chat_id,

                f"<b>"
                f"{esc(fields[index][1])}"
                f"</b>\n\n"

                "Введите новое значение."
            )


        return


    # ========================================================
    # ПРЕДПРОСМОТР
    # ========================================================

    if data == "show_preview":

        preview(
            chat_id
        )

        return


    # ========================================================
    # НАЧАТЬ ЗАНОВО
    # ========================================================

    if data == "restart_post":

        start_post(
            chat_id
        )

        return


    # ========================================================
    # ОТМЕНА
    # ========================================================

    if data == "cancel_post":

        remove_moderation_requests_for_user(
            chat_id
        )

        states.pop(
            chat_id,
            None
        )


        send(

            chat_id,

            "❌ <b>"
            "Размещение отменено."
            "</b>",

            main_menu()
        )


        return


    # ========================================================
    # ОТПРАВКА НА МОДЕРАЦИЮ
    # ========================================================

    if data == "submit_moderation":

        submit_for_moderation(
            chat_id
        )

        return



